import React, { useState, useEffect } from 'react';
import { Card } from 'antd';
import NormalRouteBuilder from '../components/FlightSearch/NormalRouteBuilder';
import NormalFlightAvailabilityCalendar from '../components/FlightSearch/NormalFlightAvailabilityCalendar';
import useNormalFlightSearch from '../components/FlightSearch/hooks/useNormalFlightSearch';

// Storage keys
const STORAGE_KEY_PREFIX = 'normal-route-builder';
const PATH_KEY = `${STORAGE_KEY_PREFIX}-path`;
const SOURCES_EXCLUDED_KEY = `${STORAGE_KEY_PREFIX}-sources-excluded`;
const API_KEY_KEY = `${STORAGE_KEY_PREFIX}-api-key`;
const DATE_RANGE_KEY = `${STORAGE_KEY_PREFIX}-date-range`;

const NormalRouteBuilderPage = () => {
  const {
    flightData,
    isLoading,
    handleSearch,
    errors,
    selectedDateRange,
    handleDateRangeSelect,
    selectedFlights,
    handleFlightSelect,
    pricingData
  } = useNormalFlightSearch();

  const [currentRoute, setCurrentRoute] = useState(null);

  // Auto-search with cached parameters on page load
  useEffect(() => {
    const cachedPath = localStorage.getItem(PATH_KEY);
    const cachedApiKey = localStorage.getItem(API_KEY_KEY);
    const cachedDateRange = localStorage.getItem(DATE_RANGE_KEY);
    const cachedSourcesExcluded = localStorage.getItem(SOURCES_EXCLUDED_KEY);

    if (cachedPath && cachedApiKey && cachedDateRange) {
      try {
        const dateRange = JSON.parse(cachedDateRange);
        const sourcesExcluded = cachedSourcesExcluded ? JSON.parse(cachedSourcesExcluded) : [];

        // Extract route segments from path
        const routeSegments = cachedPath.split(/[/-]/);
        setCurrentRoute(routeSegments);

        // Auto-search with cached parameters
        handleSearch({
          path: cachedPath,
          apiKey: cachedApiKey,
          dateRange,
          sourcesExcluded
        });

        console.log('🔄 Auto-searching with cached parameters');
      } catch (e) {
        console.error('Error auto-searching with cached parameters:', e);
      }
    }
  }, [handleSearch]);

  const handleSearchSubmit = (searchParams) => {
    const { path } = searchParams;
    // Extract route segments from path
    const routeSegments = path.split(/[/-]/);
    setCurrentRoute(routeSegments);
    handleSearch(searchParams);
  };

  return (
    <div className="flight-search-container">
      <NormalRouteBuilder 
        onSearch={handleSearchSubmit}
        isLoading={isLoading}
        errors={errors}
        externalFlightData={flightData}
      />

      {flightData && currentRoute && (
        <Card style={{ marginTop: '20px' }}>
          <NormalFlightAvailabilityCalendar
            flightData={flightData}
            currentRoute={currentRoute}
            onDateRangeSelect={handleDateRangeSelect}
            selectedRange={selectedDateRange}
          />
        </Card>
      )}

      <style jsx>{`
        .flight-search-container {
          max-width: 1920px;
          width: 100%;
          margin: 20px auto;
          padding: 0 12px;
          box-sizing: border-box;
          overflow: visible;
        }
        :global(.ant-card) {
          margin-bottom: 20px;
          width: 100%;
          overflow: visible;
        }
        @media (max-width: 768px) {
          .flight-search-container {
            padding: 0 8px;
            margin: 12px auto;
          }
        }
      `}</style>
    </div>
  );
};

export default NormalRouteBuilderPage;
